---@class PopUpGiftData
PopUpGiftData = class("PopUpGiftData")

function PopUpGiftData:initialize()
    ---@type table<number,RewardData>
    self.AwardList = {}
end

---@param msg SC_UserTimeBuy
function PopUpGiftData:SetDataByMsg(msg)
    self.giftId = msg.itemid
    self.ifbuy = msg.ifbuy
    self.overTime = msg.exptime
    self.begintime = msg.begintime
    ---@type act_gift_config_cell
    self.config = CommonHelper:GetTableDataByID(ConfigNames.act_gift_config, self.giftId)
    ---@type dictcharge_config_cell
    self.chargeCfg = CommonHelper:GetChargeCfgByAreaAndItemId(self.config.C_ID)
    self:AnalysisConfig()
end

---@return act_gift_config_cell
function PopUpGiftData:GetConfig()
    return self.config
end

function PopUpGiftData:GetEndTime()
    return self.overTime
end

function PopUpGiftData:GetType()
    return self.type
end

---@param cfg act_gift_config_cell
function PopUpGiftData:AnalysisConfig()
    self.AwardList = {}
    local ids = stringSplitToNumber(self.config.awardids, ':')
    local nums = stringSplitToNumber(self.config.awardnums, ':')
    for i = 1, #ids do
        local rewarddata = RewardData()
        rewarddata:SetDataIdNum(ids[i], nums[i])
        table.insert(self.AwardList, rewarddata)
    end
    local strs = stringSplit(self.config.giftIcon, "_")
    if #strs > 1 then
        self.type = tonumber(strs[2])
    else
        logError("  giftIcon 格式不正确  正确格式：  popupgift_type(number)_index_dt  act_gift_config_cell.C_ID:", self.config.C_ID)
    end
    if strs[#strs] ~= "dt" then
        logError("  giftIcon 格式不正确  正确格式：  popupgift_type(number)_index_dt 结尾必须是dt  act_gift_config_cell.C_ID: ", self.config.C_ID)
    end
    local list = stringSplit(self.config.name, ":")
    self.contentTable = {}
    for i, v in pairs(list) do
        table.insert(self.contentTable, v)
    end
end

function PopUpGiftData:IsActive()
    return self.ifbuy == 0 and self.overTime > CommonHelper:ConvertNowTimeDouble()
end

---@class PopUpGiftDataManager
PopUpGiftDataManager = class("PopUpGiftDataManager")

function PopUpGiftDataManager:initialize()
    ---@type table<number, PopUpGiftData>
    self.PopUpGiftDataDic = {}
    ---@type table<number, PopUpGiftData>
    self.DelayPopUpGiftData = {}
    CrossDayTrigger:Get():RegisterEvent(self,self.CrossDay)
end

function PopUpGiftDataManager:Get()
    if self._instance == nil then
        self._instance = PopUpGiftDataManager()
    end
    return self._instance
end

---@param data SC_UserTimeBuy
function PopUpGiftDataManager:UpdateData(data)
    if self.PopUpGiftDataDic[data.itemid] == nil then
        self.PopUpGiftDataDic[data.itemid] = PopUpGiftData()
        table.insert(self.DelayPopUpGiftData, self.PopUpGiftDataDic[data.itemid])
    end
    self.PopUpGiftDataDic[data.itemid]:SetDataByMsg(data)
end

---@param dataList table<number,SC_UserTimeBuy>
function PopUpGiftDataManager:UpdateDataList(dataList, isLogin)
    if isLogin then
        self:Clear()
    end
    for i, v in pairs(dataList) do
        self:UpdateData(v)
    end
    if isLogin then
        self.DelayPopUpGiftData = {}
    end
    for giftId, data in pairs(self.PopUpGiftDataDic) do
        if data.begintime > 0 then
            local v = PlayerPrefsHelper:GetValue_PopUpGift(giftId)
            if v == 0 then
                table.insert(self.DelayPopUpGiftData, data)
            end
        end
    end
    if UIManager:Get():IsPopViewShow("PopUpGiftView") then
        UIManager:Get():ClosePopup()
    end
end

function PopUpGiftDataManager:UpdateDataByMsg(data)
    self:UpdateData(data)
    for giftId, data in pairs(self.PopUpGiftDataDic) do
        if data.begintime > 0 then
            local v = PlayerPrefsHelper:GetValue_PopUpGift(giftId)
            if v == 0 then
                table.insert(self.DelayPopUpGiftData, data)
            end
        end
    end
    if UIManager:Get():IsPopViewShow("PopUpGiftView") then
        UIManager:Get():ClosePopup()
    end
end

function PopUpGiftDataManager:IsDelayPopUpShow()
    return #self.DelayPopUpGiftData > 0
end

function PopUpGiftDataManager:DelayPopUpShow()
    print("DelayPopUpShow",CommonHelper:CheckPlayerIsNewGuide())
    if CommonHelper:CheckPlayerIsNewGuide() then
        return false
    end
    if #self.DelayPopUpGiftData > 0 then
        FunctionSkipManager:Get():SkipToFunction(GameFunction.PopUpGift)
        UINotify:Get():SendNotification(UINotifyEvent.PopUpGiftView_SetPageView)
        if self.DelayPopUpGiftData[1].begintime>0 then
            PlayerPrefsHelper:SetValue_PopUpGift( self.DelayPopUpGiftData[1].giftId)
        end
        self.DelayPopUpGiftData = {}
        return true
    end
    return false
end

function PopUpGiftDataManager:DelayData()
    return self.DelayPopUpGiftData[1]
end

function PopUpGiftDataManager:CrossDay()
    if not BattleDataManager:Get():IsFighting() then
        self:DelayPopUpShow()
    end
end

---@return table<number,PopUpGiftData>
function PopUpGiftDataManager:GetActivePopUpGiftDataList()
    local list = {}
    for i, v in pairs(self.PopUpGiftDataDic) do
        if v:IsActive() then
            table.insert(list, v)
        end
    end
    return list
end

function PopUpGiftDataManager:Clear()
    self.DelayPopUpGiftData = {}
    self.PopUpGiftDataDic = {}
end